(function(){'use strict';const id=document.body.dataset.game,game=globalThis.ManagementGames[id];let storage;try{storage=globalThis.localStorage;}catch(_){storage=null;}const app=ManagementUI.mount(id,document.getElementById('challenge'),game,ArcadeChallenge,document,storage);globalThis.managementApp=app;globalThis.addEventListener('blur',()=>app.pause());globalThis.addEventListener('pagehide',event=>{if(event.persisted)app.pause();else app.destroy();});})();
